css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #018E34; text-decoration: none; }
.dcx a:hover{ color: #016E28; }
.dcx :focus-visible{ outline: 2px solid #2FCB74; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-two],.dcx [data-story],.dcx [data-cta],.dcx [data-caps]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-caps] > *,.dcx [data-cta] > *{ justify-self: center; }
.dcx #fs-hero{ max-width: 760px !important; }
.dcx #fs-checkout{ max-width: 520px !important; }
.dcx #fs-cart{ max-width: 520px !important; }
.dcx [data-feat]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-ind]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-eco]{ grid-template-columns: repeat(4, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 38px !important; }
.dcx [data-h2]{ font-size: 30px !important; }
}
@media (max-width: 640px){.dcx [data-feat],.dcx [data-ind]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-eco]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 31px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
